  $('#evaluation-run').addEventListener('change',renderEvaluation);
  $('#evaluation-verdict').addEventListener('change',()=>{if($('#evaluation-verdict').value==='uncertain')$('#evaluation-score').value='';});
  $('#evaluation-plan').addEventListener('change',async()=>{const r=current(),file=$('#evaluation-plan').files[0],epoch=++planEpoch;comparison=null;$('#evaluation-comparison').replaceChildren();if(!file||!r||r.role!=='blue')return;try{if(file.size>200000)throw Error('변경 계획은 200KB 이내');const parsed=JSON.parse(await file.text());if(epoch!==planEpoch||current()?.id!==r.id)return;const patches=FalsifyDocumentBlue.validatePlan({fileHash:r.fileHash,segments:r.segments},parsed);showComparison(r,patches,null);status('#evaluation-plan-status','출력 파일 SHA-256 일치. 검수 화면에만 보관하며 모델 입력으로 보내지 않습니다.');}catch(e){if(epoch===planEpoch)status('#evaluation-plan-status','대조 차단: '+e.message,true);}});
  $('#evaluation-form').addEventListener('submit',e=>{e.preventDefault();const r=current();if(!r)return;try{const verdict=$('#evaluation-verdict').value,score=verdict==='uncertain'?null:$('#evaluation-score').value?Number($('#evaluation-score').value):null;const v={id:crypto.randomUUID(),runId:r.id,createdAt:new Date().toISOString(),reviewer:$('#evaluation-reviewer').value.trim(),caseLabel:$('#evaluation-case').value.trim(),verdict,score,note:$('#evaluation-note').value.trim(),comparison:clone(comparison)};if(!v.reviewer||!v.caseLabel||!v.note)throw Error('평가자·사례·판정 근거가 필요합니다.');if(db.reviews.length>=1000)throw Error('검수 기록 한도 초과. 백업하세요.');persist({...db,reviews:[...db.reviews,v]});renderEvaluation();renderBoard();status('#evaluation-status','검수 이력을 추가했습니다. 이전 평가를 덮어쓰지 않았습니다. 승인/gold는 별도입니다.');}catch(err){status('#evaluation-status',err.message,true);}});
  for(const role of ['red','blue'])$('#harness-example-'+role).addEventListener('click',()=>$('#harness-editor').value=JSON.stringify({...H.builtin(role),id:'my-'+role,name:'내 '+role.toUpperCase()},null,2));
  $('#harness-example-code').addEventListener('click',()=>$('#harness-editor').value=JSON.stringify({...H.builtin('red'),id:'my-code-red',name:'내 코드 RED',adapter:{type:'stdio',executable:'C:\\Path\\To\\python.exe',args:['C:\\Path\\To\\my_harness.py']},settings:{strategy:'my-strategy'}},null,2));
  $('#harness-example-http').addEventListener('click',()=>$('#harness-editor').value=JSON.stringify({...H.builtin('blue'),id:'my-server-blue',name:'내 서버 BLUE',adapter:{type:'http',url:'https://your-server.example/falsify'},settings:{strategy:'my-strategy'}},null,2));
  $('#harness-file').addEventListener('change',async()=>{const f=$('#harness-file').files[0];if(!f)return;try{if(f.size>50000)throw Error('harness 파일은 50KB 이내');const config=H.validate(JSON.parse(await f.text()));$('#harness-editor').value=JSON.stringify(config,null,2);await previewHarness(config);status('#harness-status','편집기에 불러왔습니다. 등록·실행은 아직 하지 않았습니다.');}catch(e){$('#harness-preview').hidden=true;status('#harness-status',e.message,true);}});
  $('#harness-register').addEventListener('click',async()=>{try{await ready;const config=H.validate(JSON.parse($('#harness-editor').value)),hash=await H.hash(config);if(db.harnesses.some(h=>h.hash===hash))throw Error('이미 등록된 내용입니다. 지침/버전/설정을 바꾸세요.');if(db.harnesses.length>=100)throw Error('harness는 최대 100개');const previous=db.harnesses.filter(h=>h.config.id===config.id&&h.config.role===config.role).at(-1);const changed=previous?Object.keys(config).filter(k=>JSON.stringify(previous.config[k])!==JSON.stringify(config[k])).concat(Object.keys(previous.config).filter(k=>!(k in config))):[];persist({...db,harnesses:[...db.harnesses,{config,hash}]});$('#harness-editor').value=JSON.stringify(config,null,2);refreshHarness();status('#harness-status','새 버전 등록: '+hash+(previous?'\n이전 동일 ID에서 변경: '+changed.join(', '):'')+'\nRED / BLUE의 선택 메뉴에서 사용할 버전을 선택하세요. 등록만으로 실행하지 않습니다.');}catch(e){status('#harness-status',e.message,true);}});
  $('#harness-download').addEventListener('click',()=>{try{saveJSON(H.validate(JSON.parse($('#harness-editor').value)),'falsify-harness.json');}catch(e){status('#harness-status',e.message,true);}});
  $('#ledger-export').addEventListener('click',()=>saveJSON(db,'falsify-experiment-ledger.json'));
  $('#ledger-import').addEventListener('change',async()=>{const f=$('#ledger-import').files[0];if(!f)return;try{if(f.size>4500000)throw Error('백업은 4.5MB 이내');const imported=await validateDatabase(JSON.parse(await f.text()),true,db.runs);const next=clone(db);for(const h of imported.harnesses)if(!next.harnesses.some(x=>x.hash===h.hash))next.harnesses.push(h);for(const r of imported.runs){const old=next.runs.find(x=>x.id===r.id);if(old&&stable({...old,provenance:r.provenance})!==stable(r))throw Error('같은 실행 ID의 내용이 달라 병합을 차단했습니다.');if(!old)next.runs.push(r);}for(const v of imported.reviews){const old=next.reviews.find(x=>x.id===v.id);if(old&&stable(old)!==stable(v))throw Error('같은 검수 ID의 내용이 달라 병합을 차단했습니다.');if(!old)next.reviews.push(v);}if(next.runs.length>100||next.harnesses.length>100||next.reviews.length>1000)throw Error('병합 후 수량 한도 초과');persist(next,true);refreshHarness();refreshRuns();status('#ledger-status','백업을 병합했습니다. 가져온 기록은 출처 미검증이며 실행으로 세지 않습니다.');}catch(e){status('#ledger-status','복원 차단: '+e.message,true);}});
